712	package v1
713	
714	import (
715		"net/http"
716	
717		"connectrpc.com/connect"
718		"google.golang.org/grpc/codes"
719		"google.golang.org/grpc/status"
720	
721		"github.com/usememos/memos/proto/gen/api/v1/apiv1connect"
722	)
723	
724	// ConnectServiceHandler wraps APIV1Service to implement Connect handler interfaces.
725	// It adapts the existing gRPC service implementations to work with Connect's
726	// request/response wrapper types.
727	//
728	// This wrapper pattern allows us to:
729	// - Reuse existing gRPC service implementations
730	// - Support both native gRPC and Connect protocols
731	// - Maintain a single source of truth for business logic.
732	type ConnectServiceHandler struct {
733		*APIV1Service
734	}
735	
736	// NewConnectServiceHandler creates a new Connect service handler.
737	func NewConnectServiceHandler(svc *APIV1Service) *ConnectServiceHandler {
738		return &ConnectServiceHandler{APIV1Service: svc}
739	}
740	
741	// RegisterConnectHandlers registers all Connect service handlers on the given mux.
742	func (s *ConnectServiceHandler) RegisterConnectHandlers(mux *http.ServeMux, opts ...connect.HandlerOption) {
743		// Register all service handlers
744		handlers := []struct {
745			path    string
746			handler http.Handler
747		}{
748			wrap(apiv1connect.NewInstanceServiceHandler(s, opts...)),
749			wrap(apiv1connect.NewAuthServiceHandler(s, opts...)),
750			wrap(apiv1connect.NewUserServiceHandler(s, opts...)),
751			wrap(apiv1connect.NewMemoServiceHandler(s, opts...)),
752			wrap(apiv1connect.NewAttachmentServiceHandler(s, opts...)),
753			wrap(apiv1connect.NewAIServiceHandler(s, opts...)),
754			wrap(apiv1connect.NewShortcutServiceHandler(s, opts...)),
755			wrap(apiv1connect.NewIdentityProviderServiceHandler(s, opts...)),
756		}
757	
758		for _, h := range handlers {
759			mux.Handle(h.path, h.handler)
760		}
761	}
762	
763	// wrap converts (path, handler) return value to a struct for cleaner iteration.
764	func wrap(path string, handler http.Handler) struct {
765		path    string
766		handler http.Handler
767	} {
768		return struct {
769			path    string
770			handler http.Handler
771		}{path, handler}
772	}
773	
774	// convertGRPCError converts gRPC status errors to Connect errors.
775	// This preserves the error code semantics between the two protocols.
776	func convertGRPCError(err error) error {
777		if err == nil {
778			return nil
779		}
780		if st, ok := status.FromError(err); ok {
781			return connect.NewError(grpcCodeToConnectCode(st.Code()), err)
782		}
783		return connect.NewError(connect.CodeInternal, err)
784	}
785	
786	// grpcCodeToConnectCode converts gRPC status codes to Connect error codes.
787	// gRPC and Connect use the same error code semantics, so this is a direct cast.
788	// See: https://connectrpc.com/docs/protocol/#error-codes
789	func grpcCodeToConnectCode(code codes.Code) connect.Code {
790		return connect.Code(code)
791	}
